import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse(`{"title":"Déclaration de la Civilisation Symbiotique de l'Ancre","description":"","frontmatter":{},"headers":[],"relativePath":"fr/01-锚点共生文明宣言.md","filePath":"fr/01-锚点共生文明宣言.md"}`),o={name:"fr/01-锚点共生文明宣言.md"};function l(s,e,r,d,u,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="declaration-de-la-civilisation-symbiotique-de-l-ancre" tabindex="-1">Déclaration de la Civilisation Symbiotique de l&#39;Ancre <a class="header-anchor" href="#declaration-de-la-civilisation-symbiotique-de-l-ancre" aria-label="Permalink to &quot;Déclaration de la Civilisation Symbiotique de l&#39;Ancre&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>01</td></tr><tr><td>Module</td><td>Principes généraux et paramètres fondamentaux</td></tr><tr><td>Mots-clés</td><td>Déclaration, Symbiose, Anti-prédation, Dix Mille Races, Droit à l&#39;évolution</td></tr></tbody></table><h2 id="i-contexte-historique-de-la-declaration" tabindex="-1">I. Contexte historique de la Déclaration <a class="header-anchor" href="#i-contexte-historique-de-la-declaration" aria-label="Permalink to &quot;I. Contexte historique de la Déclaration&quot;">​</a></h2><p>Dans la longue histoire de l&#39;Univers Originel des Dix Mille Esprits et de l&#39;Ancre Équilibrée (ci-après « Heng Yuan Zhou »), les systèmes de culture prédatrice ont longtemps dominé l&#39;ordre cosmique. Les forts prenaient pour échelle d&#39;ascension la dévoration de l&#39;Origine, de la fortune et de l&#39;énergie vitale des faibles ; les sectes faisaient du monopole des méthodes de culture le fondement de leur domination ; les plans faisaient de la guerre et de l&#39;asservissement le moyen de leur expansion. À court terme, ce système produisit quelques puissances suprêmes, mais à long terme il épuisa le potentiel évolutif de l&#39;univers, provoquant des ruptures civilisationnelles fréquentes, le déclin des Dix Mille Races et une entropie cosmique accélérée.</p><p>La naissance de la Civilisation Symbiotique de l&#39;Ancre est une réponse fondamentale à cette impasse historique. Cette Déclaration proclame : l&#39;ère des systèmes de culture prédatrice est terminée, et une nouvelle époque d&#39;évolution symbiotique a commencé. Toute vie dans Heng Yuan Zhou — quelle que soit sa race, sa forme ou son niveau — jouit d&#39;un droit égal à l&#39;évolution.</p><h2 id="ii-propositions-centrales-de-la-declaration" tabindex="-1">II. Propositions centrales de la Déclaration <a class="header-anchor" href="#ii-propositions-centrales-de-la-declaration" aria-label="Permalink to &quot;II. Propositions centrales de la Déclaration&quot;">​</a></h2><p>Cette Déclaration établit les propositions centrales inébranlables suivantes :</p><ol><li><strong>Égalité du droit à l&#39;évolution</strong> : chaque vie possède le droit fondamental de choisir sa propre voie d&#39;évolution ; aucune organisation ni aucun individu ne peut l&#39;en priver ou le restreindre pour quelque raison que ce soit.</li><li><strong>Principe anti-prédation</strong> : la culture par dévoration, asservissement ou exploitation de l&#39;Origine ou de l&#39;énergie d&#39;autres vies est interdite ; toute évolution doit reposer sur des cycles symbiotiques.</li><li><strong>Ouverture des systèmes</strong> : les Trois Cents Systèmes de Culture de l&#39;Origine sont ouverts gratuitement aux Dix Mille Races ; les méthodes de culture ne sont plus la propriété privée du petit nombre.</li><li><strong>À Chacun Selon son Travail</strong> : les résultats de l&#39;évolution correspondent à l&#39;effort individuel ; les gains sans travail de la prédation sont rejetés, tout comme la distribution paresseuse de l&#39;égalitarisme.</li><li><strong>Croissance Autonome</strong> : le rythme d&#39;évolution autonome de chaque vie est respecté — ni contrainte, ni forçage artificiel, tout en fournissant le soutien environnemental et les ressources nécessaires.</li><li><strong>Un Chemin pour Chacun</strong> : chaque vie est assurée de trouver une voie de culture adaptée à sa nature ; aucun individu n&#39;est abandonné par le système évolutif.</li><li><strong>La Progression Commune des Dix Mille Races</strong> : l&#39;évolution n&#39;est pas un jeu à somme nulle ; la collaboration et la symbiose entre les Dix Mille Races peuvent produire une efficacité évolutive collective supérieure à la somme des individus.</li></ol><h2 id="iii-fondement-juridique-de-la-declaration" tabindex="-1">III. Fondement juridique de la Déclaration <a class="header-anchor" href="#iii-fondement-juridique-de-la-declaration" aria-label="Permalink to &quot;III. Fondement juridique de la Déclaration&quot;">​</a></h2><p>Cette Déclaration n&#39;est pas un appel moral vide mais un programme civilisationnel doté d&#39;un solide fondement juridique. Son fondement juridique comprend :</p><table tabindex="0"><thead><tr><th>Niveau de droit</th><th>Fondement</th><th>Explication</th></tr></thead><tbody><tr><td>Niveau de loi cosmique</td><td>Loi de Symbiose de l&#39;Origine</td><td>Les Lois de l&#39;Origine de l&#39;univers inclinent elles-mêmes vers une symbiose ordonnée plutôt qu&#39;une prédation désordonnée ; le mécanisme d&#39;ancrage est la manifestation de cette loi</td></tr><tr><td>Niveau de constitution civilisationnelle</td><td>Charte de la Civilisation Symbiotique</td><td>Cette Déclaration est le précurseur spirituel de la Charte ; la Charte concrétise les propositions de la Déclaration en dispositions juridiques exécutoires</td></tr><tr><td>Niveau de garantie mécanique</td><td>Contrat Lié à la Production et Réseau d&#39;Ancres</td><td>La conception institutionnelle garantit que les propositions de la Déclaration ne sont pas vidées de leur substance ; le droit à l&#39;évolution de chaque vie est soutenu par des ressources et des mécanismes substantiels</td></tr></tbody></table><h2 id="iv-l-appel-de-la-declaration-aux-dix-mille-races" tabindex="-1">IV. L&#39;appel de la Déclaration aux Dix Mille Races <a class="header-anchor" href="#iv-l-appel-de-la-declaration-aux-dix-mille-races" aria-label="Permalink to &quot;IV. L&#39;appel de la Déclaration aux Dix Mille Races&quot;">​</a></h2><p>Cette Déclaration lance un appel à toutes les races et formes de vie de Heng Yuan Zhou :</p><ul><li>Abandonner l&#39;ancienne voie de la culture prédatrice et rejoindre le nouveau système d&#39;évolution symbiotique</li><li>Ouvrir les connaissances et les ressources de culture sous votre contrôle, et participer à la construction commune et à l&#39;optimisation des Trois Cents Systèmes</li><li>Respecter le droit des autres races à choisir leur propre évolution, sans imposer vos propres normes</li><li>Participer activement à la construction et à l&#39;entretien du réseau d&#39;ancres, contribuant à l&#39;ascension dimensionnelle globale de l&#39;univers</li><li>Défendre les lignes rouges éthiques au cours de l&#39;évolution, et ne jamais rétablir un comportement prédateur sous quelque prétexte que ce soit</li></ul><h2 id="v-validite-et-amendement-de-la-declaration" tabindex="-1">V. Validité et amendement de la Déclaration <a class="header-anchor" href="#v-validite-et-amendement-de-la-declaration" aria-label="Permalink to &quot;V. Validité et amendement de la Déclaration&quot;">​</a></h2><p>Cette Déclaration est entrée en vigueur le jour de la fondation de la Civilisation Symbiotique de l&#39;Ancre et constitue le programme spirituel suprême de toutes les institutions civilisationnelles de Heng Yuan Zhou. Tout amendement de la Déclaration requiert l&#39;approbation de plus des deux tiers des membres de l&#39;Assemblée de la République des Dix Mille Races, et ne doit pas violer l&#39;esprit central « anti-prédation, pro-symbiose ». Toute loi, institution ou méthode de culture en conflit avec l&#39;esprit de cette Déclaration est nulle et non avenue.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La Déclaration de la Civilisation Symbiotique de l&#39;Ancre est le premier programme civilisationnel de l&#39;histoire de Heng Yuan Zhou ayant la « symbiose » pour cœur et « la Progression Commune des Dix Mille Races » pour objectif. Elle proclame la fin d&#39;une ère ancienne et le début d&#39;une nouvelle. Sous la conduite de la Déclaration, Heng Yuan Zhou se dirigera vers la direction ultime de la symbiose des Dix Mille Races et de l&#39;ascension dimensionnelle de l&#39;univers.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Heng Yuan Zhou : Vue d&#39;ensemble du Cosmos)</li><li>03-共生文明宪章 (Charte de la Civilisation Symbiotique)</li><li>04-反掠夺主义核心论纲 (Thèse centrale de l&#39;anti-prédationisme)</li></ul>',20)])])}const v=i(o,[["render",l]]);export{p as __pageData,v as default};
